/* @lc app=leetcode id=3670 lang=kotlin */ class Solution { fun maxProduct(nums: IntArray): Long = IntArray(1 shl 20).also { b -> nums.forEach { b[it] = maxOf(b[it], it) } }.also { b -> (0 until 20).forEach { bit -> b.indices.forEach { m -> if (m shr bit and 1 == 1) b[m] = maxOf(b[m], b[m xor (1 shl bit)]) } } }.let { b -> nums.maxOf { x -> x.toLong() * b[(1 shl 20) - 1 xor x] } } }